"""
01_documents.py
المرحلة الأولى من خط أنابيب RAG: تجهيز المستندات الخام (قاعدة المعرفة).

قاعدة معرفة أصلية عن أسوان تغطي: المعابد الأثرية، السد العالي، الحدائق والمتنزهات،
النزهات النيلية، المتاحف، عادات وتقاليد النوبة، الحرف اليدوية، المطبخ المحلي، والمهرجانات،
بالإضافة إلى بيانات موسّعة عن الخلفية التاريخية والعمارة والزخارف وطقوس الزواج والوفاة
والمعتقدات الشعبية والمطبخ النوبي والنصائح السياحية.
"""

DOCUMENTS = [{'id': 0, 'category': 'معابد', 'text': 'معبد فيلة يقع على جزيرة أجيليكيا بعد نقله من موقعه الأصلي إنقاذاً له من مياه بحيرة ناصر، وهو مخصص لعبادة الإلهة إيزيس ويعد من أجمل المعابد المصرية على الإطلاق.'}, {'id': 1, 'category': 'معابد', 'text': 'يقام في معبد فيلة عرض للصوت والضوء في المساء يحكي أسطورة إيزيس وأوزوريس، ويجذب هذا العرض آلاف الزوار سنوياً للاستمتاع بالإضاءة الملونة على أعمدة المعبد.'}, {'id': 2, 'category': 'معابد', 'text': 'معبدا أبو سمبل الكبير والصغير نحتهما رمسيس الثاني في الصخر تخليداً لانتصاراته وتكريماً لزوجته الملكة نفرتاري، ويقعان جنوب أسوان على بحيرة ناصر.'}, {'id': 3, 'category': 'معابد', 'text': 'تحدث ظاهرة تعامد الشمس على وجه رمسيس الثاني داخل معبد أبو سمبل مرتين كل عام، في الثاني والعشرين من فبراير والثاني والعشرين من أكتوبر، ويحضرها آلاف الزوار من أنحاء العالم.'}, {'id': 4, 'category': 'معابد', 'text': 'معبد كلابشة يعد من أكبر المعابد النوبية التي تم نقلها وإعادة بنائها بالقرب من السد العالي، وهو مخصص لعبادة الإله ماندوليس رب الشمس عند النوبيين.'}, {'id': 5, 'category': 'معابد', 'text': 'معبد بيت الوالي يقع بجوار معبد كلابشة وهو منحوت في الصخر، ونقشت جدرانه بمشاهد حربية تصور انتصارات رمسيس الثاني على النوبيين والليبيين.'}, {'id': 6, 'category': 'معالم أثرية', 'text': 'المسلة الناقصة تقع في المحاجر الشمالية بأسوان، وهي أكبر مسلة معروفة في مصر القديمة، تُظهر شقوقاً في الجرانيت أوقفت استكمال نحتها وفصلها عن الصخر.'}, {'id': 7, 'category': 'معالم أثرية', 'text': 'توضح المسلة الناقصة للزوار طريقة قدماء المصريين في استخراج المسلات من محاجر الجرانيت، وتعتبر شاهداً مهماً على تقنيات النحت والنقل في العصر الفرعوني.'}, {'id': 8, 'category': 'معالم أثرية', 'text': 'جزيرة الفنتين تقع وسط النيل أمام مدينة أسوان مباشرة، وتضم آثار معبد خنوم وقرى نوبية ملونة ومتحف أسوان الذي يعرض قطعاً من مختلف العصور.'}, {'id': 9, 'category': 'سدود', 'text': 'السد العالي بأسوان أحد أهم المشروعات الهندسية في القرن العشرين، شُيّد لحماية مصر من الفيضانات وتوليد الكهرباء وتخزين المياه في بحيرة ناصر.'}, {'id': 10, 'category': 'سدود', 'text': 'خزان أسوان القديم الذي بُني في بدايات القرن العشرين يقع جنوب مدينة أسوان مباشرة، ويعد من أوائل السدود الكبرى التي أقيمت على نهر النيل.'}, {'id': 11, 'category': 'حدائق ومتنزهات', 'text': 'جزيرة كتشنر، المعروفة أيضاً بالحديقة النباتية، تضم مئات الأنواع النادرة من النباتات والأشجار الاستوائية التي جمعها اللورد كتشنر من مختلف أنحاء العالم.'}, {'id': 12, 'category': 'حدائق ومتنزهات', 'text': 'يفضل الزوار التجول في الحديقة النباتية بجزيرة كتشنر عصراً حيث يمكن مشاهدة الطيور النادرة والاستمتاع بمناظر النيل الهادئة بين أشجار النخيل والمانجو.'}, {'id': 13, 'category': 'حدائق ومتنزهات', 'text': 'كورنيش أسوان يمتد على طول ضفة النيل الشرقية، وهو مكان مفضل للمشي والفسحة العائلية مساءً، ويضم مقاهي ومطاعم مطلة مباشرة على النهر.'}, {'id': 14, 'category': 'نزهات نيلية', 'text': 'رحلات الفلوكة في أسوان من أشهر أنشطة الترفيه، حيث يستقل السياح والزوار المحليون قوارب شراعية تقليدية للتجول بين الجزر الصخرية عند الغروب.'}, {'id': 15, 'category': 'نزهات نيلية', 'text': 'يمكن للزائر استئجار فلوكة من الكورنيش للإبحار حول جزيرة النباتات وجزيرة الفنتين، وتعد رحلة المساء وقت الغروب من أجمل التجارب في أسوان.'}, {'id': 16, 'category': 'متاحف', 'text': 'المتحف النوبي يعرض تاريخ وحضارة النوبة عبر العصور من خلال قطع أثرية ومجسمات وأزياء تقليدية، وقد أُنشئ ضمن مشروع إنقاذ آثار النوبة الدولي.'}, {'id': 17, 'category': 'متاحف', 'text': 'متحف أسوان يقع في مبنى قديم على جزيرة الفنتين ويعرض مقتنيات اكتُشفت في المنطقة، من تماثيل وأواني فخارية تعود لعصور فرعونية ورومانية مختلفة.'}, {'id': 18, 'category': 'ثقافة وعادات', 'text': 'يتميز النوبيون بألوانهم الزاهية في تزيين منازلهم، حيث تُطلى الجدران بألوان مبهجة وتُرسم عليها زخارف تمثل النخيل والتماسيح رمزاً للحماية والخصوبة.'}, {'id': 19, 'category': 'ثقافة وعادات', 'text': 'من عادات النوبيين الترحيب بالضيوف بتقديم القهوة أو الشاي فور الوصول، وتعد الضيافة جزءاً أساسياً من الهوية النوبية المعروفة بكرمها.'}, {'id': 20, 'category': 'ثقافة وعادات', 'text': 'يحتفظ سكان النوبة بلغتهم الخاصة وأغانيهم الشعبية المصحوبة بآلة الطار والدف، وتُنقل هذه التقاليد الشفهية من جيل إلى جيل حتى اليوم.'}, {'id': 21, 'category': 'ثقافة وعادات', 'text': 'السبوع هو احتفال تقليدي يقام في اليوم السابع لميلاد الطفل في أسوان والنوبة، حيث يجتمع الأهل والجيران وتُغنى أغاني خاصة بهذه المناسبة.'}, {'id': 22, 'category': 'ثقافة وعادات', 'text': 'تشتهر حفلات الزفاف النوبية بطقوس تمتد لعدة أيام، منها ليلة الحناء التي تُزيَّن فيها العروس بنقوش تقليدية وسط غناء ورقص جماعي.'}, {'id': 23, 'category': 'حرف يدوية', 'text': 'الحرف اليدوية النوبية مثل نسج السلال الملونة من سعف النخيل وصناعة الخرز والتطريز اليدوي تشكل مصدر دخل مهم للنساء في القرى النوبية.'}, {'id': 24, 'category': 'قرى وأسواق', 'text': 'القرى النوبية القريبة من أسوان مثل قرية غرب سهيل تجذب الزوار لمشاهدة البيوت الملونة والتفاعل مع التماسيح الأليفة التي يربيها بعض السكان.'}, {'id': 25, 'category': 'قرى وأسواق', 'text': 'سوق أسوان الشعبي يمتد بمحاذاة الكورنيش ويعرض التوابل الملونة والبخور والمنتجات النوبية اليدوية، ويعد وجهة مفضلة للتسوق والتجول مساءً.'}, {'id': 26, 'category': 'مطبخ محلي', 'text': 'الكركديه هو المشروب الأشهر في أسوان، يُصنع من نبات الكركديه المزروع محلياً، ويُقدَّم بارداً أو ساخناً وله شهرة تتجاوز حدود مصر.'}, {'id': 27, 'category': 'مطبخ محلي', 'text': 'يعتمد المطبخ النوبي على أطباق مثل الويكة والفتة النوبية والتمر واللحوم المطهوة ببطء، وتتميز الوجبات بنكهات مميزة موروثة عن أجداد النوبة.'}, {'id': 28, 'category': 'طبيعة', 'text': 'الجندل الأول هو منطقة الصخور الجرانيتية التي تعيق الملاحة جنوب أسوان، وتشكل مناظرها الطبيعية الفريدة مصدر جذب للزوار الباحثين عن هدوء النيل.'}, {'id': 29, 'category': 'طبيعة', 'text': 'تشتهر أسوان بمناخها الجاف الدافئ طوال العام تقريباً، مما يجعلها وجهة مثالية للسياحة الشتوية والاستشفاء من أمراض الروماتيزم والجهاز التنفسي.'}, {'id': 30, 'category': 'مهرجانات', 'text': 'مهرجان تعامد الشمس على معبد أبو سمبل يتحول إلى احتفال شعبي وفني كبير يضم عروضاً فلكلورية نوبية وفعاليات موسيقية تستمر طوال اليوم.'}, {'id': 31, 'category': 'أنشطة سياحية', 'text': 'تعد رحلة ركوب الجمال في الصحراء المحيطة بأسوان ومشاهدة غروب الشمس من أعلى التلال الرملية من الأنشطة المفضلة لدى السياح الباحثين عن مغامرة.'}, {'id': 32, 'category': 'أنشطة سياحية', 'text': 'بحيرة ناصر تتيح رحلات بحرية فاخرة لعدة أيام تمر بالمعابد النوبية المنقولة مثل أبو سمبل وكلابشة وعمدا، وتمنح تجربة مختلفة عن النيل التقليدي.'}, {'id': 33, 'category': 'مواصلات وموقع', 'text': 'تقع مدينة أسوان في أقصى جنوب مصر على الضفة الشرقية لنهر النيل، وتبعد عن القاهرة نحو تسعمائة كيلومتر ويمكن الوصول إليها بالطائرة أو القطار.'}, {'id': 34, 'category': 'عمارة نوبية', 'text': 'يُبنى البيت النوبي التقليدي من الطين اللبن على حافة الصحراء بين الجبل ونهر النيل، ويتكون غالباً من حوش مستطيل تحيط به الغرف، ومدخله الرئيسي يواجه النيل مباشرة.'}, {'id': 35, 'category': 'عمارة نوبية', 'text': 'تخلو أغلب البيوت النوبية من النوافذ الكبيرة، وتكتفي بفتحات علوية صغيرة تسمى الطاقات لتفادي برودة رياح الشتاء والحفاظ على برودة المنزل في فصل الصيف.'}, {'id': 36, 'category': 'زخارف ورموز', 'text': 'يزين النوبيون واجهات منازلهم برسوم هندسية ونباتية وحيوانية ملونة، ويُعتقد أن الغرض الأساسي منها هو درء الحسد وحماية أهل البيت من العين الحاسدة.'}, {'id': 37, 'category': 'زخارف ورموز', 'text': 'من أشهر الزخارف النوبية المثلث الذي يرمز للحماية من الحسد والسحر، والدائرة التي ترمز للشمس والقمر، والهلال الذي يوحي بالتفاؤل، والسمكة رمزاً للبعث وتجدد الحياة.'}, {'id': 38, 'category': 'حرف يدوية', 'text': 'تبرع النساء النوبيات في نسج أطباق وسلال من خوص النخيل ومراوح من الجريد، وتُعلَّق هذه المشغولات اليدوية على حوائط وأسقف المنزل لأغراض الزينة والحماية معاً.'}, {'id': 39, 'category': 'أزياء تقليدية', 'text': 'ترتدي المرأة النوبية جلباباً أسود واسع الأكمام يسمى التوب فوق جلباب آخر ملون، مع غطاء رأس يسمى الشبارة وخلخال في القدمين وحلية جلدية ملونة تتدلى على الصدر.'}, {'id': 40, 'category': 'أزياء تقليدية', 'text': 'يرتدي العريس النوبي يوم زفافه جلباباً أبيض وعمامة بيضاء ويحمل سيفاً وخنجراً رمزاً للشجاعة والرجولة، وينتعل حذاءً تقليدياً يسمى المركوب.'}, {'id': 41, 'category': 'طقوس الزواج', 'text': 'تبدأ مراسم الزواج النوبي بيوم يسمى بيرار نهار، حين تزور عائلة العريس بيت العروس حاملة الهدايا، ويُتفق خلاله على تفاصيل الزواج ومهر العروس وتُقرأ الفاتحة.'}, {'id': 42, 'category': 'طقوس الزواج', 'text': 'في مراسم تسمى أوكجر تطوف نساء عائلة العريس على بيوت القرية لإبلاغ الجيران بموعد الزفاف، حاملات طبقاً مزيناً بالزهور والعطور يسمى الكريدة.'}, {'id': 43, 'category': 'طقوس الزواج', 'text': 'ليلة الحناء عند النوبيين تسمى كوفري تور وتُعد من أقدس ليالي الزفاف، حيث تُزين العروس بالحناء وسط الغناء الفولكلوري والرقص الجماعي قبل ليلة الزفاف بيوم أو يومين.'}, {'id': 44, 'category': 'طقوس الزواج', 'text': 'من عادات الزواج النوبي أن يتحمل العريس الجزء الأكبر من تكاليف التجهيزات دون اشتراط قائمة عفش على العروس، وتندر حالات الطلاق في المجتمعات النوبية مقارنة بغيرها.'}, {'id': 45, 'category': 'طقوس الزواج', 'text': 'يفضّل المجتمع النوبي زواج الأقارب خصوصاً بين أبناء العمومة حفاظاً على تماسك العائلة والهوية النوبية، وهو ما يُعرف بنمط الزواج الداخلي.'}, {'id': 46, 'category': 'عادات المولود', 'text': 'بعد الولادة تمكث الأم فترة في بيت أهلها لترعاها والدتها، وتحرص العائلة على تقديم أطعمة مقوية خلال فترة النفاس وتجنّب خروج الأم من المنزل إلا للضرورة القصوى.'}, {'id': 47, 'category': 'طقوس الوفاة', 'text': 'عند وفاة أحد أفراد القرية النوبية يشارك جميع السكان في مراسم العزاء والدفن، ولا تحضر النساء عادة موكب تشييع الجنازة بل ينتظرن في المنزل لاستقبال المعزين.'}, {'id': 48, 'category': 'خلفية تاريخية', 'text': 'يُعتقد أن اسم النوبة مشتق من الكلمة المصرية القديمة نب وتعني الذهب، نسبة إلى مناجم الذهب التي اشتهرت بها المنطقة منذ العصور الفرعونية القديمة.'}, {'id': 49, 'category': 'خلفية تاريخية', 'text': 'ينقسم سكان النوبة المصرية تقليدياً إلى ثلاث مجموعات رئيسية هي الكنوز والفديجا والعرب، ولكل مجموعة لهجتها وبعض عاداتها الخاصة رغم تجاورها الجغرافي على امتداد النيل.'}, {'id': 50, 'category': 'طب شعبي', 'text': 'اعتمد أهل النوبة تاريخياً على طب شعبي مستمد من الأعشاب والنباتات البرية المحلية لعلاج بعض الأعراض البسيطة، إلى جانب استفادتهم من الخدمات الصحية الحديثة المتوفرة حالياً.'}, {'id': 51, 'category': 'خلفية تاريخية', 'text': 'يرجع أصل اسم النوبة إلى الكلمة المصرية القديمة "نب" التي تعني الذهب، نسبة إلى مناجم الذهب التي اشتهرت بها المنطقة، وقد صنف قدماء المصريين النوبيين إلى فئتين: النوبة السفلى المعروفة باسم "واوات"، والنوبة العليا المعروفة باسم "كوش".'}, {'id': 52, 'category': 'خلفية تاريخية', 'text': 'ينقسم سكان النوبة المصرية تقليدياً إلى ثلاث طوائف رئيسية هي الكنوز والفاديجا والعرب (العليقات)، ولكل طائفة منطقتها الجغرافية ولغتها وعاداتها الخاصة، ويعتبر الكنوز أنفسهم أصحاب أصل عربي، بينما تتحدث الفاديجا اللهجة الأقرب للغة النوبية القديمة.'}, {'id': 53, 'category': 'عمارة نوبية', 'text': 'يُبنى البيت النوبي من الطوب اللبن، وتُسقف الغرف بجريد النخيل أو سيقان الحصير عند محدودي الدخل، بينما تُستخدم أسقف من اللبن على عوارض خشبية أو على هيئة قباب عند الميسورين، وتخلو أغلب البيوت من النوافذ الكبيرة وتكتفي بفتحات علوية صغيرة تسمى الطاقات لتفادي برودة الشتاء والحفاظ على برودة المكان صيفاً.'}, {'id': 54, 'category': 'زخارف ورموز', 'text': 'كثيراً ما يكتب النوبي عبارات لدرء العين الحاسدة أو جلب الخير على مدخل داره، كما يكتب اسم صاحب الدار على واجهة المنزل، ويعلو سطح البيت النوبي كورنيش من العرائس أو المعينات المتراصة لأغراض الحماية من الحسد.'}, {'id': 55, 'category': 'زخارف ورموز', 'text': 'المثلث في الفن النوبي رمز للحماية من الحسد والوقاية من السحر، بينما ترمز الدائرة إلى الشمس والقمر، ويوحي الهلال بالتفاؤل، وترمز السمكة للبعث وإعادة الحياة، ويُستخدم المعين كحلية في العقود والمكاحل وكنارات الطرح.'}, {'id': 56, 'category': 'حرف يدوية', 'text': 'تبرع النساء النوبيات في نسج أطباق وسلال من خوص النخيل ومراوح من الجريد، وتُعلَّق هذه المشغولات على الحوائط والأسقف داخل البيت النوبي، ويُعتقد أن تعليقها يكتب للحياة الزوجية الاستمرار والبقاء، ويحميها من شر الحسد.'}, {'id': 57, 'category': 'طقوس الزواج', 'text': 'تبدأ مراسم الزواج النوبي بيوم يسمى "بيرار نهار"، حيث تزور عائلة العريس ورفاقه بيت العروس حاملين الهدايا، ويتحدثون مع أهلها في تفاصيل الزواج والمهر، وتُقرأ الفاتحة ويتحدد موعد الزفاف.'}, {'id': 58, 'category': 'طقوس الزواج', 'text': 'في مراسم "أوكجر" تطوف أم العريس مع بعض فتيات العائلة على بيوت القرية لإبلاغ الجيران بموعد الزفاف، حاملات طبقاً مزيناً بالورد يسمى "الكريدة" ووعاءً من العطور النوبية التقليدية مثل الصندل والمحلب.'}, {'id': 59, 'category': 'طقوس الزواج', 'text': 'تسمى ليلة الحناء عند النوبيين "كوفري تور"، وتُعد من أقدس ليالي الزفاف، حيث تُزين العروس بالحناء وسط الغناء الفولكلوري والرقص الجماعي، وتُقام قبل ليلة الزفاف بيوم أو يومين.'}, {'id': 60, 'category': 'طقوس الزواج', 'text': 'في يوم الزفاف الرسمي، تُذبح الذبائح ويجتمع أهل القرية لتناول وليمة الغداء، وتقام طقوس تسمى "الكرا" أو "النقوط" وهي مساعدة مالية يقدمها الحضور، ثم تسير زفة الرجال والسيدات لتصل إلى بيت العروس بالمدائح النبوية.'}, {'id': 61, 'category': 'طقوس الزواج', 'text': 'يفضّل المجتمع النوبي زواج الأقارب خصوصاً بين أبناء العمومة، وهو ما يُعرف بنمط الزواج الداخلي، ويهدف إلى الحفاظ على تجانس العائلة وتماسكها وهويتها النوبية، وتندر حالات الطلاق في المجتمعات النوبية مقارنة بغيرها.'}, {'id': 62, 'category': 'طقوس الزواج', 'text': 'من طقوس يوم السابع للزفاف عند النوبيين ما يسمى "الكولود"، حيث يحمل العريس جريدة نخل خضراء منقوشة بسبعة تجاويف مملوءة بالعطور، ويطوف العروسان على سبعة منازل للأقارب، وفي كل منزل يُستقبلان بالفشار والبلح وقطعة ذهبية أو هدية رمزية.'}, {'id': 63, 'category': 'طقوس الزواج', 'text': 'يمثل الذهب ركيزة أساسية في مهر العروس النوبية، ومن أبرز مشغولاته القلادة الذهبية المعروفة بـ"القمر بوبة" التي تغطي الصدر حتى الخصر وقد يصل وزنها إلى نحو 250 جراماً، إضافة إلى عدد من الغوايش والخواتم.'}, {'id': 64, 'category': 'عادات المولود', 'text': 'بعد الولادة تمكث الأم فترة في بيت أهلها ترعاها والدتها اعتقاداً بأن ذلك يعجل بحمل قادم، وتحرص العائلة على تقديم أطعمة مقوية ومشروب الحلبة خلال فترة النفاس مع تجنّب خروج الأم من المنزل إلا للضرورة.'}, {'id': 65, 'category': 'عادات المولود', 'text': 'السبوع هو احتفال قديم يقام في اليوم السابع لميلاد الطفل، وتتضمن عاداته القديمة غسل وجه الطفل بمياه النيل ورش اللبن، إلا أن هذه العادة تراجعت بعد ابتعاد بعض النوبيين عن ضفاف النيل.'}, {'id': 66, 'category': 'طقوس الوفاة', 'text': 'عند وفاة أحد أفراد القرية النوبية تبدأ النساء بالصراخ والعويل وتتوالى الصرخات في أنحاء القرية، ويحرص جميع أهل القرية على المشاركة في مراسم العزاء والدفن، ولا يُسمح للنساء بحضور موكب تشييع الجنازة.'}, {'id': 67, 'category': 'معتقدات شعبية', 'text': 'من معتقدات النوبيين أن وفاة شخص يوم الاثنين تعني أن غيره سيموت بعده بالتتابع، فيقومون بكسر صحن صيني أمام باب منزل المتوفى لمنع ذلك، كما يقدمون خليطاً من الروائح العطرية "حل الرماد" لأفراد أسرة المتوفى.'}, {'id': 68, 'category': 'معتقدات شعبية', 'text': 'يعتقد بعض النوبيين أن ليلة عاشوراء هي الليلة التي وصلت فيها سفينة سيدنا نوح إلى الشاطئ بسلام، وأنها الليلة التي عبر فيها سيدنا موسى البحر، وتعد النذور من المعتقدات الشائعة في حياة النوبيين خاصة النساء.'}, {'id': 69, 'category': 'معتقدات شعبية', 'text': 'يظهر الاعتقاد بالسحر لدى أهل النوبة في الوشم والرسوم الموجودة على الجدران والتي يزينون بها واجهات المنازل ومداخلها، وكذلك في مشغولات الخرز والزخارف التي يعتقدون أنها تحميهم من الحسد والعين.'}, {'id': 70, 'category': 'طب شعبي', 'text': 'اعتمد أهل النوبة تاريخياً على طب شعبي مستمد من الأعشاب والنباتات البرية المحلية لعلاج أعراض مثل الصداع ولدغة العقرب والمغص، إلى جانب استفادتهم من الخدمات الصحية الحديثة المتوفرة حالياً.'}, {'id': 71, 'category': 'مطبخ محلي', 'text': 'الجاكود من أشهر الأكلات النوبية التقليدية، ويُحضّر من الخضروات الورقية الخضراء كالسبانخ أو الملوخية المطهوة في مرق اللحم والمتبلة بالبصل والثوم، ويُفرك الخليط بأداة خشبية تقليدية تسمى "المفراك" ثم يُقدَّم مع خبز "عيش الدوكة".'}, {'id': 72, 'category': 'مطبخ محلي', 'text': 'الويكة طبق نوبي يُصنع من البامية الخضراء المقطعة والمطهوة في المرق، وبعد نضجها تُفرك للحصول على قوام سميك يشبه الملوخية، ثم تُغطى بطشة من الثوم المقلي وتُقدَّم مع عيش الدوكة.'}, {'id': 73, 'category': 'مطبخ محلي', 'text': '"عيش الدوكة" هو الخبز النوبي الأشهر، ويُحضّر من عجينة سائلة خفيفة تُفرد سريعاً على صاج حديدي دائري يسمى "الدوكة" لتنضج في ثوانٍ على شكل رقائق ناعمة، وتُستخدم كقاعدة لغمس الأطباق النوبية المختلفة.'}, {'id': 74, 'category': 'مطبخ محلي', 'text': 'الأبريه مشروب تراثي ورمضاني يُصنع من رقائق قمح مخمرة مخبوزة بسماكة هشة، تُكسر وتُضاف إلى عصير الليمون البارد أو الكركديه، ويشتهر بقدرته على إطفاء العطش في أيام الصيف الحارة.'}, {'id': 75, 'category': 'مطبخ محلي', 'text': '"الجبنة" هي طقس القهوة التراثي في جنوب مصر، وتُحضّر بتحميص حبوب القهوة الخضراء يدوياً ثم طحنها مع الهيل والزنجبيل والقرنفل، وتُغلى في إبريق فخاري يُسمى الجبنة على الفحم وتُقدَّم في فناجين صغيرة.'}, {'id': 76, 'category': 'مطبخ محلي', 'text': 'يعتبر الفول المدمس المطبوخ ببطء الطبق الوطني الأشهر في مصر ويُقدَّم مع الخبز الطازج والطحينة والليمون، بينما يعد الكشري من أشهر الأطباق النباتية ويتكون من الأرز والعدس والحمص والمعكرونة في صلصة الطماطم مع البصل المقرمش.'}, {'id': 77, 'category': 'مطبخ محلي', 'text': 'يعتمد المطبخ النوبي على أطباق سمك الفرخ النيلي المقلي أو المشوي المقدم مع الأرز المتبل، أما السحلب فهو مشروب مصري ساخن كريمي يُصنع من جذر الأوركيد والحليب والقرفة ويُقدَّم في الليالي الباردة، بجانب عصير قصب السكر الطازج المستخرج بمعصرة تقليدية.'}, {'id': 78, 'category': 'قرى وأسواق', 'text': 'جزيرة سهيل واحدة من أقدم جزر أسوان، وكانت تُستخرج منها الجرانيت الأسواني قديماً، وتضم نقوشاً تاريخية ومقاييس مياه قديمة، وتُعد اليوم مزاراً سياحياً للتعرف على ثقافة الشعب النوبي وتقاليده.'}, {'id': 79, 'category': 'قرى وأسواق', 'text': 'قرية غرب سهيل قرية نوبية سياحية أُنشئت منذ نحو قرن أثناء تشييد الخزان القديم، وتتميز بيوتها بألوانها المبهجة وقبابها التقليدية، ويمارس بعض سكانها عادة تربية التماسيح داخل منازلهم كعرض سياحي.'}, {'id': 80, 'category': 'طبيعة', 'text': 'محمية سالوجا وغزال من أصغر المحميات الطبيعية في مصر بمساحة نحو 55 فداناً، وتقع عند الشلال الأول شمال خزان أسوان، وتضم أنواعاً نباتية نادرة وأكثر من 60 نوعاً من الطيور المهاجرة أبرزها طائر أبو منجل الأسود.'}, {'id': 81, 'category': 'معالم أثرية', 'text': 'قبة الهوا، أو "قبة النبلاء"، مجموعة مقابر صخرية كانت تخص حكام الأقاليم وكبار رجال الدولة من الدولة القديمة حتى الوسطى، وتتميز بموقعها على ضفاف النيل والإطلالة الساحرة على مدينة أسوان.'}, {'id': 82, 'category': 'معالم أثرية', 'text': 'ضريح الآغا خان مقبرة رخامية تقع على تلة مرتفعة تطل على النيل بالضفة الغربية أمام أسوان، وهو مثوى السير سلطان محمد شاه آغا خان الثالث الزعيم الروحي للطائفة الإسماعيلية، ويجمع تصميمه بين عناصر العمارة الفاطمية والأنماط الحديثة.'}, {'id': 83, 'category': 'معالم أثرية', 'text': 'دير الأنبا سمعان أحد أكبر وأقدم الأديرة القبطية، يقع في الصحراء الغربية على بعد نحو 10 كيلومترات شمال أسوان، ويعود تاريخه إلى القرن السابع الميلادي، ويمكن الوصول إليه بالجمال أو سيارات الدفع الرباعي.'}, {'id': 84, 'category': 'مواصلات وموقع', 'text': 'يمكن الوصول إلى أسوان عن طريق الطيران المباشر من القاهرة والمدن الرئيسية، أو بالقطار الذي يستغرق نحو 12 ساعة ليلاً من القاهرة، أو بالسيارة عبر الصحراء الشرقية في رحلة تستغرق نحو 10-11 ساعة.'}, {'id': 85, 'category': 'مواصلات وموقع', 'text': 'يعتمد التنقل داخل أسوان بشكل أساسي على سيارات الأجرة التي يُتفق على أجرتها مسبقاً لعدم وجود عدادات، إضافة إلى قوارب الأجرة التي تربط بين الجزر مثل جزيرة كيتشنر والعبارات العامة لعبور النيل.'}, {'id': 86, 'category': 'قرى وأسواق', 'text': 'يضم سوق أسوان العربي، الواقع بالقرب من الكورنيش، أكشاكاً تبيع الهدايا التذكارية والتوابل والمنسوجات والمجوهرات، بينما يوفر بازار النوبة تجربة تسوق نوبية أكثر أصالة بمصنوعات يدوية ملونة وسلال وفخار.'}, {'id': 87, 'category': 'أنشطة سياحية', 'text': 'من أبرز الأنشطة الليلية في أسوان حضور عرض الصوت والضوء في معبد فيلة الذي يروي أسطورة إيزيس وأوزوريس، والتنزه على كورنيش النيل مساءً، أو احتساء الشاي في شرفة فندق أولد كاتاراكت التاريخي المطل على النيل وجزيرة الفنتين.'}, {'id': 88, 'category': 'أنشطة سياحية', 'text': 'يمكن للزائر تجربة ركوب منطاد الهواء الساخن فوق أسوان للحصول على إطلالة بانورامية على المعالم الأثرية والمناظر الطبيعية، إلى جانب رحلات الكروز النيلية الفاخرة بين أسوان والأقصر التي تمر بمعابد كوم أمبو وإدفو.'}, {'id': 89, 'category': 'أعياد ومناسبات', 'text': 'للنوبيين طقوس خاصة في عيد الأضحى، حيث تشهد قرى مركز نصر النوبة استعدادات لاستقبال أبناء العمومة المقيمين في الشمال، وتُجهَّز المخبوزات والوجبات التقليدية، ويحرص الشباب على ارتداء الزي النوبي، الجلباب للرجال والجرجار للفتيات.'}, {'id': 90, 'category': 'أعياد ومناسبات', 'text': 'تحافظ قبائل العبابدة والبشارية جنوب أسوان على عاداتها الخاصة في الأعياد، ومن أبرز أطباقها التقليدية لحم "السُلات" المشوي على الجمر، ووجبة "الأوتم" المصنوعة من الدقيق ولبن الإبل، ومشروب "الجبّنة" الذي يتصدر موائدهم.'}, {'id': 91, 'category': 'ثقافة وعادات', 'text': 'يتزوج الشاب النوبي عادة في سن يتراوح بين 18 و22 عاماً، بينما تتزوج الفتاة بين 15 و20 عاماً، ويُعد الزواج المبكر من العادات المنتشرة في المجتمع النوبي حتى وقت قريب.'}, {'id': 92, 'category': 'ثقافة وعادات', 'text': 'يُعد الطلاق من الأمور المكروهة بشدة عند النوبيين نظراً لتقديسهم الحياة الزوجية، ولا يحدث إلا في أضيق الحدود وبشروط معينة كعدم الإنجاب أو الإصابة بمرض مزمن.'}, {'id': 93, 'category': 'معالم أثرية', 'text': 'المسلة الناقصة كتلة واحدة من الجرانيت الوردي يبلغ طولها نحو 43 متراً وتنتهي بقمة هرمية، وتُعد أحد أبرز الألغاز الأثرية التي حيّرت علماء الآثار حول أسباب توقف نحتها وبقائها متصلة بالصخر الأم.'}, {'id': 94, 'category': 'نصائح سياحية', 'text': 'يُنصح بزيارة أسوان خلال أشهر الشتاء من نوفمبر إلى مارس حين تكون درجات الحرارة معتدلة نهاراً بين 20 و25 درجة مئوية، أو خلال موسمي الكتف في أبريل ومايو أو سبتمبر وأكتوبر لتجنب الحرارة الشديدة مع حشود أقل وأسعار أفضل.'}, {'id': 95, 'category': 'نصائح سياحية', 'text': 'يُفضّل عند التخطيط لزيارة أسوان اختيار ملابس قطنية خفيفة نظراً لارتفاع الحرارة والرطوبة، مع إحضار قبعة ونظارة شمسية ومنتجات حماية من الشمس، وحجز رحلة أبو سمبل الجوية مسبقاً في حال اختيار الطيران الداخلي.'}]


